def set_left_most_unset_bit(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1  # leftmost unset bit is the highest bit of 0, which is bit 0

    # Find the position of the leftmost set bit
    bit_length = n.bit_length()

    # If all bits below the highest bit are set (e.g. 0b111), then the leftmost unset bit
    # is the next bit after the highest set bit
    all_ones = (1 << bit_length) - 1
    if n == all_ones:
        # Set the next bit
        return n | (1 << bit_length)

    # Otherwise, find the leftmost unset bit within the current bit_length
    # We'll check bits from the highest down to 0
    for pos in reversed(range(bit_length)):
        if not (n & (1 << pos)):
            return n | (1 << pos)

    # This line should never be reached because above cases are exhaustive
    return n
```

